// ═══════════════════════════════════════════════════════════════
// IDL-001: Yalnızca kesin yanıt beklenen koşullarda _lastReply kaydet
// ═══════════════════════════════════════════════════════════════
if (input.action === 'reply' && input.expectsReply === true && !input.pauseAutomation && senderNumber) {
  if (!staticData._lastReply) staticData._lastReply = {};
  staticData._lastReply[senderNumber] = Date.now();
